-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann ich als Azubi einen Tarifvertrag ablehnen?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt automatisch bei Tarifbindung"}, {"text": "Ja", "correct": false, "because": "Betrieb ist gebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss mein Betrieb an einen Tarifvertrag gebunden sein?', 2, '[{"text": "Nein", "correct": true, "because": "Freiwillig für Unternehmen"}, {"text": "Ja", "correct": false, "because": "Nur bei Mitgliedschaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist meine Vergütung im Tarifvertrag geregelt?', 2, '[{"text": "Ja", "correct": true, "because": "Tarif legt Lohn fest"}, {"text": "Nein", "correct": false, "because": "Typische Regelung"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich ohne Tarifvertrag mehr verdienen?', 2, '[{"text": "Ja", "correct": true, "because": "Individuelle Verhandlung möglich"}, {"text": "Nein", "correct": false, "because": "Tarif oft Mindeststandard"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Regelt der Tarifvertrag meine Arbeitszeit?', 2, '[{"text": "Ja", "correct": true, "because": "Arbeitszeit ist enthalten"}, {"text": "Nein", "correct": false, "because": "Standardbestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Tarifvertrag meine Pausen vorschreiben?', 2, '[{"text": "Ja", "correct": true, "because": "Pausenregelung üblich"}, {"text": "Nein", "correct": false, "because": "Teil des Vertrags"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Tarifvertrag für alle Azubis gleich?', 2, '[{"text": "Nein", "correct": true, "because": "Je nach Branche unterschiedlich"}, {"text": "Ja", "correct": false, "because": "Variiert regional"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich ohne Tarifvertrag weniger Urlaub haben?', 2, '[{"text": "Ja", "correct": true, "because": "Tarif sichert oft mehr"}, {"text": "Nein", "correct": false, "because": "Gesetzlicher Mindesturlaub gilt"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Wer verhandelt Tarifverträge?', 2, '[{"text": "Gewerkschaften", "correct": true, "because": "Vertreten Arbeitnehmer"}, {"text": "Azubis", "correct": false, "because": "Keine Verhandlungsmacht"}, {"text": "Regierung", "correct": false, "because": "Nicht beteiligt"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin sagt, der Tarifvertrag gilt für mich. Was bedeutet das für meinen Lohn?', 3, '[{"text": "Festgelegter Mindestlohn", "correct": true, "because": "Tarif bindet Betrieb"}, {"text": "Ich verhandle selbst", "correct": false, "because": "Tarif übernimmt"}, {"text": "Kein Lohn", "correct": false, "because": "Unsinn"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regelung findet sich typisch in einem Tarifvertrag?', 2, '[{"text": "Urlaubstage", "correct": true, "because": "Standardbestandteil"}, {"text": "Kündigungsfrist eines Kunden", "correct": false, "because": "Kein Bezug"}, {"text": "Betriebsfarben", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter meint, wir haben einen neuen Tarifvertrag. Was könnte sich ändern?', 3, '[{"text": "Mehr Gehalt", "correct": true, "because": "Häufiges Ziel"}, {"text": "Weniger Arbeitszeit", "correct": false, "because": "Möglich, aber nicht sicher"}, {"text": "Neue Uniformen", "correct": false, "because": "Kein Tarifthema"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was kann ein Tarifvertrag regeln?', 4, '[{"text": "Gehalt", "correct": true, "because": "Kernbestandteil"}, {"text": "Arbeitszeit", "correct": true, "because": "Wichtige Regelung"}, {"text": "Urlaub", "correct": true, "because": "Standardthema"}, {"text": "Büroausstattung", "correct": false, "because": "Kein Tarifinhalt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt ein Tarifvertrag für Azubis?', 3, '[{"text": "Feste Vergütung", "correct": true, "because": "Sicherheit"}, {"text": "Geregelte Arbeitszeiten", "correct": true, "because": "Schutz"}, {"text": "Mehr Urlaub", "correct": true, "because": "Oft besser als Gesetz"}, {"text": "Freie Kaffeewahl", "correct": false, "because": "Kein Tarifthema"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir diskutieren über den Tarifvertrag. Was könnte ich erwarten?', 3, '[{"text": "Gehaltserhöhung", "correct": true, "because": "Häufiges Ergebnis"}, {"text": "Zusatzleistungen", "correct": true, "because": "Mögliche Boni"}, {"text": "Kündigungsschutz", "correct": true, "because": "Arbeitnehmerschutz"}, {"text": "Firmenwagen", "correct": false, "because": "Nicht üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist an einem Tarifvertrag beteiligt?', 4, '[{"text": "Gewerkschaften", "correct": true, "because": "Vertreten Arbeitnehmer"}, {"text": "Arbeitgeberverbände", "correct": true, "because": "Vertreten Betriebe"}, {"text": "Betriebe", "correct": true, "because": "Tarifgebundene Firmen"}, {"text": "Kunden", "correct": false, "because": "Nicht beteiligt"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Tarifvertrag gilt nur für Gewerkschaftsmitglieder. b) Er regelt Arbeitsbedingungen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Gilt für alle im Betrieb, Bedingungen ja"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Tarifverträge können Urlaub erhöhen. b) Sie sind für jeden Betrieb Pflicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Urlaub ja, Pflicht nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Tarifvertrag kann Überstunden regeln. b) Er gilt nur für Azubis.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überstunden ja, alle Mitarbeiter"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Tarifverträge werden regelmäßig neu verhandelt. b) Sie ersetzen den Ausbildungsvertrag.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Neuverhandlung ja, Ergänzung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

